//! Complete frozen-original/shared/native DATA comparison; finite Pages issue no host authority.
use crate::manual_log_policy::*;
#[path="../fixtures/original_policies/manual_log_original.rs"]mod frozen;
#[path="../fixtures/native-manual-log/fixture.rs"]mod fixture;
use crate::{captured_raw_tree_pages::{Policy,Data},captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure};
use std::{path::Path,sync::Arc,io};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,stop:bool}
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{if self.stop{return Ok(false)}for(relative,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
struct Text<'a>(&'a Data);impl crate::baseline::SiteText for Text<'_>{fn site_text(&self,rel:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(s,_)|s.rel==rel&&s.line as usize==line).expect("current original source line").1.clone()}}
fn record(outcome:&crate::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn pages<'a>(root:&'a Path,budget:&Arc<Budget>)->Pages<'a>{let mut rows=Vec::new();for(relative,text)in fixture::FILES{if Policy::ManualLog.selects_path(relative){let source=dm_preprocess::AcquiredSource::from_original_bytes(text.as_bytes().to_vec(),());rows.push(((*relative).to_string(),source.lease().source_text().clone()));}}rows.reverse();Pages{root,rows,budget:Arc::clone(budget),stop:false}}
#[test]fn manual_log_complete_frozen_original_and_shared_and_native_reports_match_every_site_allow_scope_and_text(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/manual_log_original.rs"))),"788ea44488f3a5c53d159e4f8ae5f429d48831ac");for case in 0..4{let root=crate::test_scratch::dir(&format!("manual-log-original-{case}"));for(relative,text)in fixture::FILES{let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}let configuration=fixture::configuration(case);let path=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,&configuration).unwrap();let options=crate::run::Options{root:root.clone(),lints:vec![fixture::NAME.into()],raw:true,no_cache:true,..Default::default()};let mut registry=crate::lint::Registry::default();frozen::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());assert!(expected.internal_error.is_none());let mut registry=crate::lint::Registry::default();crate::lints::sys_dx_manual_fingerprint_log::register(&mut registry);let shared=crate::run::Engine::new(registry,options).unwrap();assert_eq!(record(&shared.run_one(shared.reg.lints[0].as_ref())),record(&expected));
 if case==0{assert!(expected.run.sites.iter().any(|s|s.rel=="maps/handler.dm"));assert!(expected.run.sites.iter().any(|s|old.tree.site_text(&s.rel,s.line as usize).contains("cross-file selected")));assert!(expected.run.sites.iter().any(|s|old.tree.site_text(&s.rel,s.line as usize).contains("typed reference child")));assert!(expected.run.sites.iter().any(|s|old.tree.site_text(&s.rel,s.line as usize).contains("global reference")));assert!(expected.allow_used.iter().any(|a|a.name=="sys_dx_manual_fingerprint_log"));assert!(!expected.run.sites.iter().any(|s|s.rel.contains(".hidden")||s.rel.contains("unit_tests")||old.tree.site_text(&s.rel,s.line as usize).contains("not selected")));}
 let budget=Budget::new(128*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(configuration.as_bytes())).unwrap();let data=crate::captured_raw_tree_pages::collect(&pages(&root,&budget),Policy::ManualLog,&config,&budget,&||Ok(())).unwrap();assert_eq!(data.sites(),expected.run.sites.as_slice());assert_eq!(data.allow_used(),expected.allow_used.as_slice());assert_eq!(data.notes(),expected.run.notes.as_slice());for(site,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize));}let empty=Default::default();let scope=config.borrowed_report_scope(fixture::NAME,"sys").unwrap_or(&empty);let actual=crate::policy_finish::finish_report(Policy::ManualLog.metadata(),scope,&Text(&data),crate::lint::Run{sites:data.sites().to_vec(),notes:data.notes().to_vec()},data.allow_used().to_vec(),Default::default(),&root,&None,true,|_,_,_|panic!("ordinary Sites policy has no custom hook"),|_,_|false);assert_eq!(record(&actual),record(&expected));println!("MANUAL_LOG_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
#[test]fn manual_log_checked_growth_and_mid_source_actual_error_precede_later_failure_and_recover(){let root=std::env::current_dir().unwrap().join("manual-log-actual-source-control");let ample=Budget::new(128*1024*1024).unwrap();let mut exercised=false;crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/control.dm"),format!("/obj/control/proc/act_work(user)\n{}","    add_fingerprint(user)\n".repeat(2048)).into(),0,&ample,&mut|_,views|{let file=views.source_file()?;let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&denied,poll:&||Ok(())};let mut temp=crate::captured_allow_annotations::Operation{budget:&ample,poll:&||Ok(())};assert!(matches!(facts_of_using(file,&mut keep,&mut temp),Err(Failure::Operational(ref actual))if actual.kind()==io::ErrorKind::OutOfMemory));let count=std::cell::Cell::new(0usize);let poll=||{let n=count.get()+1;count.set(n);if n==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let mut keep=crate::captured_allow_annotations::Operation{budget:&ample,poll:&poll};assert!(matches!(facts_of_using(file,&mut keep,&mut temp),Err(Failure::Operational(ref actual))if actual.raw_os_error()==Some(1450)));assert_eq!(count.get(),32);let mut keep=crate::captured_allow_annotations::Operation{budget:&ample,poll:&||Ok(())};let facts=facts_of_using(file,&mut keep,&mut temp)?;assert!(!assemble(&[(file.rel.as_str(),&facts)],&mut keep)?.is_empty());exercised=true;Ok(true)}).unwrap();assert!(exercised);let config=Config::capture(crate::captured_raw_policy::Configuration::ProvenMissing).unwrap();let mut source=pages(&root,&ample);source.stop=true;assert!(matches!(crate::captured_raw_tree_pages::collect(&source,Policy::ManualLog,&config,&ample,&||Ok(())),Err(Failure::Unsupported(message))if message.contains("EOF")));source.stop=false;assert!(!crate::captured_raw_tree_pages::collect(&source,Policy::ManualLog,&config,&ample,&||Ok(())).unwrap().sites().is_empty());}
